from copy import deepcopy
from m1_conteudos import quiz,option

ADDITIONAL={
'01':[
 quiz('Poder dizer que não','Situação inventada: uma escola publica um vídeo de uma atividade. Só depois pergunta às pessoas filmadas se concordam.','O que faz falta para falar de consentimento informado?',['Saber previamente como será usada a imagem e poder recusar sem pressão.','Receber muitos elogios depois da publicação.','Participar na atividade significa aceitar todos os usos futuros da imagem.'],0,'O consentimento exige informação adequada e liberdade de decisão. Estar presente numa atividade não equivale a aceitar automaticamente qualquer divulgação.'),
 dict(type='branch',title='Uma proteção que admite perguntas',scene='Situação inventada: um adulto diz que uma decisão é para proteger um jovem e recusa explicar o motivo.',question='Qual deve ser o próximo passo?',options=[option('Pedir a explicação e uma possibilidade de ser ouvido.','Uma explicação permite compreender o risco e discutir alternativas. A proteção ganha fundamento quando a pessoa afetada pode participar de forma adequada.'),option('Concluir que qualquer proteção é sempre controlo.','A proteção pode ser necessária. É preciso analisar o risco, a justificação, os meios usados e a possibilidade de participação.'),option('Aceitar porque a palavra «proteção» resolve o problema.','A palavra não demonstra, por si só, que a medida é adequada. Compara a finalidade anunciada com os seus efeitos.')])],
'02':[
 quiz('A pista que contraria','Situação inventada: acreditas que alguém te excluiu de um grupo de propósito. Encontras uma mensagem que sugere um erro na lista.','Que atitude torna a investigação mais rigorosa?',['Ignorar a mensagem porque já escolheste uma explicação.','Examinar a nova informação e verificar se altera a hipótese.','Tratar a hipótese inicial e a nova mensagem como igualmente provadas.'],1,'Uma hipótese pode ser revista. A investigação não existe apenas para confirmar a primeira explicação: procura também dados que a ponham à prova.'),
 quiz('O que a imagem mostra','Vês numa fotografia uma pessoa de braços cruzados num grupo.','Qual é a frase que distingue descrição de interpretação?',['A pessoa está de braços cruzados; não sei, só por isso, se está zangada.','A pessoa está de braços cruzados, logo não quer participar.','Cruzar os braços demonstra sempre uma posição de autoridade.'],0,'A posição dos braços é observável. O sentimento e a intenção precisam de mais contexto. Uma pista pode ajudar uma interpretação sem a tornar obrigatória.')],
'03':[
 quiz('Discordar sem excluir','Uma pessoa apresenta uma opinião que consideras errada.','Que resposta reconhece a dignidade e mantém a discussão crítica?',['Negar-lhe qualquer possibilidade de responder.','Aceitar a opinião porque todas as opiniões são igualmente verdadeiras.','Contestar a ideia com razões e respeitar o direito da pessoa a responder.'],2,'Respeitar a pessoa não obriga a concordar com a ideia. Uma discussão pode ser exigente e, ao mesmo tempo, tratar o outro como interlocutor.'),
 dict(type='branch',title='Quem é parecido comigo?',scene='Situação inventada: descobres que uma pessoa ridicularizada online tem interesses muito parecidos com os teus.',question='O que deve pesar na tua avaliação?',options=[option('A semelhança ajuda-me a compreender, mas o respeito já lhe era devido antes.','A empatia pode tornar a situação mais próxima. A dignidade oferece uma base que também protege quem não tem interesses parecidos com os teus.'),option('Só agora passa a merecer que a defendam.','Os direitos não dependem da semelhança entre as pessoas. A descoberta pode mudar a tua perceção, mas não cria a dignidade da outra pessoa.'),option('Se não tivesse esses interesses, a ridicularização seria aceitável.','A diferença de gostos não justifica um tratamento humilhante. Pergunta pelo efeito sobre a pessoa, não apenas pelo que tens em comum com ela.')])],
'04':[
 quiz('As mesmas palavras','Texto original: «Fica aqui.» Numa leitura, a personagem procura ajuda; noutra, tenta impedir uma fuga.','O que mudou necessariamente?',['As palavras da fala.','O objetivo e a relação da ação com as circunstâncias.','O número de pessoas na sala.'],1,'As palavras podem manter-se e a ação mudar. O objetivo, a situação e a forma de dirigir a fala alteram o que ela faz na relação.'),
 quiz('Compreender a escolha','Consegues explicar por que motivo Marlon tem interesse em cumprir o papel.','O que ainda falta analisar?',['Os efeitos sobre Truman e a possibilidade de Marlon agir de outra maneira.','Nada: explicar um motivo torna a ação justa.','Apenas se a representação convence o público.'],0,'A análise do motivo ajuda a compreender. A avaliação ética considera também os efeitos, os direitos e as alternativas. Uma ação tecnicamente convincente pode produzir um dano.')],
'05':[
 quiz('O que falta ao exemplo?','Uma frase de um ensaio diz apenas: «Truman tenta sair de barco».','Que continuação transforma o relato em análise?',['«O barco está no mar e o filme continua.»','«Gosto muito desta cena.»','«A tentativa mostra que valoriza poder escolher, mesmo quando sair implica incerteza.»'],2,'A continuação explica o que a cena permite pensar sobre a liberdade. O exemplo fica ligado ao argumento, em vez de servir apenas de resumo.'),
 quiz('Uma objeção que merece resposta','Tese: uma vida confortável pode não ser uma vida livre.','Qual é a objeção mais pertinente para desenvolver?',['Algumas pessoas podem preferir limitar certas escolhas em troca de segurança: como distinguir esse acordo de um controlo imposto?','O filme foi realizado há muitos anos.','A personagem tem um nome de que não gosto.'],0,'A objeção incide sobre a relação entre liberdade e segurança. A resposta deve discutir informação, consentimento e possibilidade real de revisão do acordo.')],
'06':[
 quiz('Antes de condenar','Uma pessoa foi acusada de uma ação grave. A acusação ainda não foi demonstrada num processo justo.','O que exige a presunção de inocência?',['Tratar a acusação como prova de culpa.','Não tratar a culpa como estabelecida apenas por existir uma acusação.','Garantir que qualquer pessoa acusada nunca pode ser responsabilizada.'],1,'O princípio não impede a investigação ou a responsabilização fundada. Impede que a acusação, por si só, substitua a demonstração necessária.'),
 quiz('O mesmo objeto, perguntas diferentes','Uma arma pode aparecer numa peça, numa performance ou num processo judicial.','Qual é a comparação mais rigorosa?',['Identificar o contexto e o que o objeto permite perguntar em cada situação.','Concluir que as três situações têm o mesmo consentimento e o mesmo risco.','Usar a expectativa do público como prova de que uma ação aconteceu.'],0,'A função narrativa, o perigo real e o valor de uma prova são problemas distintos. A comparação ganha sentido quando explica relações e diferenças.')],
'07':[
 quiz('Quem responde pela ordem?','Quem executou uma exclusão afirma: «Eu só transmiti o que me disseram».','Qual é a pergunta mais útil para continuar?',['Qual era a justificação, que efeito produziu e que possibilidade existia de pedir esclarecimento?','Quem falou mais alto?','A pessoa afetada é popular?'],0,'A cadeia de transmissão deve ser analisada. Ter recebido uma ordem não explica automaticamente se era legítima nem quais as alternativas de quem a executou.'),
 quiz('A pausa','Uma personagem demora a responder a uma pergunta.','Qual é a atitude de leitura mais rigorosa?',['Classificar a pausa sempre como medo.','Ignorar a pausa porque não contém palavras.','Relacionar a pausa com as falas, a situação e o que a personagem procura.'],2,'A pausa pode ter efeitos diferentes. A interpretação precisa de relacionar pistas, em vez de aplicar uma legenda fixa a todos os silêncios.')],
'08':[
 quiz('O salto que fazemos','Texto original: A diz «Hoje não consigo». B conclui «Nunca se pode contar com ela».','Qual é o salto da interpretação?',['Transformar uma dificuldade situada numa definição geral da pessoa.','Distinguir dois momentos do dia.','Pedir mais informação antes de concluir.'],0,'«Hoje» limita a afirmação a uma situação. «Nunca» generaliza. A segunda frase precisa de outras evidências e pode impedir que a pessoa seja ouvida.'),
 quiz('Voz e autora','Uma voz de uma peça faz uma afirmação violenta ou contraditória.','O que permite a leitura concluir com rigor?',['A autora defende sempre tudo o que todas as suas personagens dizem.','É preciso analisar a função dessa voz e a relação com o conjunto da obra.','A obra só pode ser entendida pela biografia da autora.'],1,'Uma obra pode pôr posições em conflito. Identificar a função de uma fala exige leitura e contexto; não basta igualar a voz dramática à autora.')],
'09':[
 quiz('Uma minoria fundamentada','Uma pessoa discorda do grupo e apresenta uma informação relevante.','O que deve o grupo fazer?',['Aceitar automaticamente a discordância porque é minoritária.','Ignorar a informação para manter a união.','Examinar a informação e permitir que as razões sejam discutidas.'],2,'A posição minoritária não está certa por ser minoritária. Tem direito a ser examinada pelas razões e evidências, tal como uma posição maioritária.'),
 quiz('O discurso convincente','Uma personagem fala com segurança e ocupa o centro da sala.','Que distinção é importante?',['A força da apresentação pode ser analisada separadamente da qualidade das razões.','O centro da sala demonstra que a pessoa tem razão.','Falar com segurança substitui verificar a informação.'],0,'A interpretação torna o discurso eficaz, mas a eficácia não garante verdade ou justiça. É preciso ouvir as razões e analisar como são apresentadas.')],
'10':[
 quiz('Duas páginas, uma origem','Duas páginas repetem a mesma afirmação e citam exatamente a mesma publicação inicial.','O que podes concluir sobre a confirmação?',['São necessariamente duas confirmações independentes.','Podem depender da mesma origem; é preciso verificar a fonte inicial.','Nenhuma das páginas pode conter informação verdadeira.'],1,'A repetição não equivale a confirmação independente. A origem pode ser boa ou fraca: é isso que a investigação precisa de examinar.'),
 quiz('Comparar sem apagar diferenças','Vais relacionar Truman e os jurados do segundo filme.','Que frase abre uma comparação fundamentada?',['Os filmes são exatamente iguais porque têm pessoas.','Um filme tem cores e o outro é a preto e branco, por isso não há relação possível.','Truman é impedido de conhecer a situação; os jurados têm de avaliar informação. Em ambos, importa a relação entre conhecimento e poder.'],2,'A comparação identifica uma diferença e um problema comum. A partir daí, precisa de exemplos e de explicar o que revelam sobre direitos humanos e democracia.')]
}

SUPPORT={
'01':'Pergunta o que a pessoa sabe, se pode recusar e quem controla as consequências.',
'02':'Distingue a observação da explicação que propões. Uma conclusão precisa de pistas que a sustentem.',
'03':'Distingue gostar de uma pessoa, compreender a sua posição e reconhecer os seus direitos.',
'04':'Separa o que a personagem pretende daquilo que faz. Depois, pergunta pelos efeitos sobre o outro.',
'05':'Procura a ligação entre uma posição, uma razão e um exemplo. Um detalhe do filme não explica sozinho uma tese.',
'06':'Identifica o contexto: narrativa, performance ou decisão sobre factos. A mesma palavra pode abrir problemas diferentes.',
'07':'Procura a origem e a justificação da ordem. Um silêncio deve ser lido na relação com a situação.',
'08':'Distingue o que foi dito do que alguém concluiu sobre a pessoa. Reconhece a informação que falta.',
'09':'Separa a contagem de posições da análise das razões. Maioria e minoria também precisam de fundamento.',
'10':'Pergunta de onde vem a informação, a que questão responde e como pode ser verificada.'
}
def enrich(steps):
 result=deepcopy(steps)
 for s in result:
  original=s['rounds'];extra=deepcopy(ADDITIONAL[s['id']])
  s['rounds']=[extra[0],*original,extra[1]]
  for r in s['rounds']:r.setdefault('support',SUPPORT[s['id']])
 return result
